calcdose:[{"k": 1, "s": "How many mg of lidocaine are in 10 mL of 1%?", "o": ["100 mg", "10 mg", "1,000 mg", "1 mg"], "e": "Step 1: 10 mg/mL × 10."}, {"k": 2, "s": "A 20 kg child needs 15 mg/kg paracetamol; 250 mg/5 mL suspension. Volume?", "o": ["6 mL", "3 mL", "12 mL", "1.2 mL"], "e": "Step 2: 300 mg ÷ 50 mg/mL."}, {"k": 3, "s": "Amoxicillin 500 mg TDS for 7 days as 250 mg/5 mL. Total volume?", "o": ["210 mL", "105 mL", "70 mL", "420 mL"], "e": "Step 3: 10 mL × 3 × 7."}, {"k": 4, "s": "An 8-year-old has anaphylaxis. IM adrenaline 1 in 1,000?", "o": ["300 micrograms (0.3 mL)", "150 micrograms (0.15 mL)", "500 micrograms (0.5 mL)", "300 micrograms (3 mL)"], "e": "Step 4: 6 to 12 years."}, {"k": 5, "s": "Which is the safest way to write this dose?", "o": ["Levothyroxine 50 micrograms", "Levothyroxine 50 mcg", "Levothyroxine .05 mg", "Levothyroxine 50.0 micrograms"], "e": "Step 5: in full, no trailing or leading decimal traps."}],
calcopioid:[{"k": 1, "s": "A patient takes morphine MR 30 mg twice daily. What figure do you convert from?", "o": ["60 mg oral morphine a day", "30 mg", "15 mg", "120 mg"], "e": "Step 1: the 24-hour total."}, {"k": 2, "s": "Oral morphine 120 mg a day → SC diamorphine over 24 hours?", "o": ["40 mg", "60 mg", "120 mg", "20 mg"], "e": "Step 2: divide by 3."}, {"k": 3, "s": "A fentanyl 25 micrograms/hour patch ≈ what oral morphine a day?", "o": ["60 mg", "25 mg", "250 mg", "12 mg"], "e": "Step 3: 12 ≈ 30, so 25 ≈ 60."}, {"k": 4, "s": "Morphine MR 60 mg twice daily. Breakthrough dose?", "o": ["20 mg", "60 mg", "120 mg", "5 mg"], "e": "Step 4: 120 ÷ 6."}, {"k": 5, "s": "Prednisolone 40 mg ≈ which dexamethasone dose?", "o": ["6 mg", "40 mg", "0.75 mg", "160 mg"], "e": "Step 5: 40 ÷ 5 × 0.75."}],
